public static class LingFengLegacyColorTable
{
    // 翎风/HeroM2 的 ColorTable 是 256 个 BGRA 四元组；脚本颜色编号直接索引该表。
    private static readonly byte[] Bytes = Convert.FromBase64String(
        "");

    public static bool TryGetRgb(int index, out byte red, out byte green, out byte blue)
    {
        if (index is < byte.MinValue or > byte.MaxValue)
        {
            red = green = blue = 0;
            return false;
        }

        int offset = index * 4;
        blue = Bytes[offset];
        green = Bytes[offset + 1];
        red = Bytes[offset + 2];
        return true;
    }
}
